+            if let Ok(i) = raw.parse::<i64>() {
+                Value::Number(i.into())
+            } else if let Ok(f) = raw.parse::<f64>()
+                && f.is_finite()
+                && let Some(n) = serde_json::Number::from_f64(f)
+            {
+                Value::Number(n)
+            } else {
+                Value::String(raw.to_owned())
+            }
+        }
+    }
