+                let r = fields::named(
+                    ui.add(DragValue::new(&mut f).speed(0.1).range(lo..=hi)),
+                    &opt.title,
+                );
+                r.changed()
+            });
+            if changed {
+                *val = OptionValue::Float(f);
+            }
+            changed
+        }
+        OptionKind::String => {
+            let shown = match val {
+                OptionValue::Str(s) => s.clone(),
+                _ => String::new(),
+            };
